import {createWorld,player,rand,roles,weapons,stats,overall,value,uniques,modes,terrainInfo,nextFixture,enemyRoster,Battle,finishFixture,advance,clamp} from './engine.js';
import {ArenaView} from './arena.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='arena-manager-save-v1';let state;try{const raw=localStorage.getItem(key);state=raw?JSON.parse(raw):createWorld();if(state.version!==1||!Array.isArray(state.players))throw Error('Invalid save');}catch{state=createWorld();}
function normalizeDiscoveryNews(s){
 for(const n of s.news||[]){
  if(n.title==='유니크 선수 발견'){
   const name=n.text?.split(' — ')[0];
   n.title='자유계약 시장 소식';
   n.text=name?`${name} 선수가 자유계약 시장에 등록되었습니다.`:'새 선수가 자유계약 시장에 등록되었습니다.';
  }
 }
}
normalizeDiscoveryNews(state);
let tab='command',arena=null,battle=null,series=null,running=false,speed=4,rosterFilter='',roleFilter='',marketFilter='',selected=new Set((state.lineup||state.players.slice(0,20).map(p=>p.id)).filter(id=>state.players.some(p=>p.id===id))),lastTick=0,uiTick=0;
const date=()=>{const d=new Date(Date.UTC(state.season,0,5+state.day));return `${d.getUTCFullYear()}.${String(d.getUTCMonth()+1).padStart(2,'0')}.${String(d.getUTCDate()).padStart(2,'0')}`;};
const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const portrait=(p,cls='portrait')=>p.portrait==null?`<div class="${cls} portrait-fallback">${esc(p.name[0])}</div>`:`<img class="${cls}" src="assets/portrait-${p.portrait}.webp" alt="${esc(p.name)} 초상화" loading="lazy">`;
const icon=(type)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${{command:'<path d="m4 17 5-9 4 6 4-10 3 13z"/><path d="M4 21h16"/>',roster:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v2"/>',tactics:'<path d="M5 5h14v14H5zM5 12h14M12 5v14"/><circle cx="8" cy="8" r="1"/><circle cx="16" cy="16" r="1"/>',market:'<path d="M4 7h16l-2 13H6zM8 7V5a4 4 0 0 1 8 0v2"/>',facilities:'<path d="M3 21h18M5 21V8l7-5 7 5v13M9 21v-7h6v7"/>',league:'<path d="M8 3h8v6a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v5m-4 3h8m-6-3h4"/>',relations:'<path d="M12 20 4 12a5 5 0 0 1 8-6 5 5 0 0 1 8 6z"/>'}[type]}</svg>`;
const nav=[['command','지휘실'],['roster','선수단'],['tactics','전술 설정'],['market','이적 시장'],['facilities','육성 · 시설'],['league','리그 현황'],['relations','인물 관계']];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function save(silent=true){state.lineup=[...selected];try{localStorage.setItem(key,JSON.stringify(state));if(!silent)toast('이 컴퓨터에 저장했습니다.');}catch{toast('저장 공간이 부족합니다. 저장 파일을 내보내세요.');}}
function ranked(){return [...state.table].sort((a,b)=>b.wins-a.wins||(b.for-b.against)-(a.for-a.against));}
function shell(){if(arena){arena.dispose();arena=null;}$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">AR<em>E</em>NA</div><div class="brand-sub">GLADIATOR MANAGER</div><div class="club-side"><div class="club-mark">E</div><div><strong>${esc(state.club)}</strong><small>${state.division||'도시 리그'} · 대한민국</small></div></div><nav class="nav" aria-label="게임 메뉴">${nav.map(([id,label])=>`<button data-nav="${id}" class="${id===tab?'active':''}" ${series&&!series.finished?'disabled':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidebar-foot"><div>FIRST SEASON · v0.1</div><div>기기 내 싱글플레이 저장</div><button data-action="export" class="ghost">저장 파일 내보내기</button><button data-action="import" class="ghost">저장 파일 불러오기</button><button data-action="reset" class="ghost">새 게임</button><input id="save-file" type="file" accept="application/json" hidden></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${state.season} SEASON / ROUND ${Math.min(state.round+1,14)}</div><strong>${date()} <span class="muted">· 감독실</span></strong></div><div class="top-actions"><div class="balance">₩ ${state.budget.toLocaleString()} <small>백만원</small></div><span class="saved">자동 저장</span><button data-action="save" class="ghost" ${series&&!series.finished?'disabled':''}>저장</button><button data-action="day" class="primary" ${series&&!series.finished?'disabled':''}>다음 날</button></div></header><div class="content" id="content"></div></main></div>`;renderContent();}
function title(kicker,text,sub='',actions=''){return `<div class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${text}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>`;}
function renderContent(){if(arena){arena.dispose();arena=null;}const c=$('#content');if(tab==='command')renderCommand(c);if(tab==='roster')renderRoster(c);if(tab==='tactics')renderTactics(c);if(tab==='market')renderMarket(c);if(tab==='facilities')renderFacilities(c);if(tab==='league')renderLeague(c);if(tab==='relations')renderRelations(c);}
function mountArena(){try{arena=new ArenaView($('#viewport'),battle);}catch(e){$('#viewport').insertAdjacentHTML('afterbegin','<div class="empty">3D 화면을 시작할 수 없습니다. 브라우저의 하드웨어 가속을 확인하세요. 문자 중계와 경기 진행은 사용할 수 있습니다.</div>');console.error(e);}}
function renderCommand(c){const f=nextFixture(state),rank=ranked().findIndex(t=>t.id===0)+1;const active=series&&!series.finished;if(!battle||(!series&&battle.done)){const roster=state.players.filter(p=>!p.injury);const opponents=enemyRoster(state);battle=new Battle([roster,opponents],0,state.seed,state.tactic,f?.terrain||'city');}const mi=active?series.mode:0;
c.innerHTML=title('MATCHDAY CONTROL','경기 지휘실',active?'선수들의 움직임을 읽고 전술을 조정하세요.':'오늘의 선수단과 다음 경기를 준비하세요.',`<span class="pill lime">${state.division||'도시 리그'}</span>`)+`${series?.finished?`<div class="result"><h2>${series.wins[0]>series.wins[1]?'경기 승리':'경기 패배'} <span class="number">${series.wins.join(' : ')}</span></h2><p>${series.opponent}전이 종료되었습니다. 기록과 경기 수입을 반영했습니다.</p><button class="primary" data-action="close-result">다음 경기 준비</button></div>`:''}<div class="arena-layout"><section class="panel battle-panel"><div class="match-strip"><div class="team-name">${esc(state.club)}</div><div class="match-score" id="match-score">${series?series.wins.join(' : '):'0 : 0'}</div><div class="team-name enemy">${esc(series?.opponent||f?.opponent.name||'시즌 종료')}</div></div><div class="panel-head"><div class="set-chips">${modes.map((m,i)=>`<span class="set-chip ${active&&i===series.mode?'current':''} ${series?.results[i]===0?'win':series?.results[i]===1?'loss':''}" id="chip-${i}">${i+1} ${m.name}</span>`).join('')}</div><span class="arena-status" id="timer">${clock(battle.time)} / 60:00</span></div><div class="viewport" id="viewport"><div class="arena-overlay"><span class="pill teal" id="mode-label">${modes[mi].n} : ${modes[mi].n} ${modes[mi].name}</span> <span class="pill">${terrainInfo[battle.terrain].name} 아레나</span></div><div class="arena-bottom" id="arena-count">${active?'경기 진행 중':'선수 입장 · 경기 시작을 기다립니다'}</div><div class="camera-controls"><button data-camera="rotate" aria-label="카메라 회전">회전</button><button data-camera="in" aria-label="확대">＋</button><button data-camera="out" aria-label="축소">－</button></div></div><div class="arena-controls"><div class="controls-left"><button data-action="pause" id="pause" ${!active?'disabled':''}>${running?'일시정지':'재생'}</button><select id="speed" aria-label="경기 재생 속도">${[1,4,12,32].map(x=>`<option value="${x}" ${speed===x?'selected':''}>${x}배속</option>`).join('')}</select><button data-action="quick" ${!active?'disabled':''}>결과까지</button></div><div class="legend"><span><b></b>우리 팀</span><span><b class="enemy"></b>상대 팀</span></div></div><div class="panel-head"><h2>실시간 중계</h2><span class="muted" id="live-score"></span></div><div class="log" id="log"></div></section><aside class="side-stack">${active?`<section class="panel"><div class="panel-head"><h2>전술 지시</h2><span class="pill lime">LIVE</span></div><div class="panel-body"><select class="full" id="live-tactic" aria-label="경기 중 전술">${['균형','공격','수비'].map(x=>`<option ${state.tactic===x?'selected':''}>${x}</option>`).join('')}</select><p class="muted">지시는 다음 행동부터 적용됩니다.</p><div class="info" id="mode-rule">${modes[mi].rule}</div></div></section><section class="panel"><div class="panel-head"><h2>출전 선수 상태</h2></div><div class="status-list" id="status-list"></div></section>`:`<section class="panel fixture"><div class="eyebrow">NEXT FIXTURE</div><div class="big">${f?'ROUND '+(state.round+1):'SEASON END'}</div><h3>${f?f.opponent.name:'시즌 최종 순위 확정'}</h3><span class="pill">${f?(f.home?'홈 경기':'원정 경기'):'최종 '+rank+'위'}</span><div class="fixture-details"><span class="muted">경기장</span><strong>${terrainInfo[f?.terrain||'city'].name}</strong></div><div class="fixture-details"><span class="muted">대회 방식</span><strong>5판 3선승</strong></div><button class="primary" data-action="${f?'kickoff':'new-season'}">${f?'경기 시작':'다음 시즌 시작'}</button></section><section class="panel mini-stat"><label>등록 선수</label><div class="flex spread"><span class="value">${state.players.length}<small class="muted"> / 30</small></span><button class="ghost" data-nav="roster">선수단</button></div><div class="bar"><i style="width:${state.players.length/30*100}%"></i></div></section><section class="panel mini-stat"><label>현재 순위</label><div class="flex spread"><span class="value">${rank}<small class="muted"> / 8</small></span><span class="pill">${state.table[0].wins}승 ${state.table[0].losses}패</span></div></section>`}</aside></div><div class="grid two section-gap"><section class="panel"><div class="panel-head"><h2>구단 소식</h2><span class="muted">${state.news.length}건</span></div>${state.news.slice(0,3).map(n=>`<div class="news-row"><div class="flex spread"><strong>${esc(n.title)}</strong><span class="eyebrow">DAY ${n.day}</span></div><p>${esc(n.text)}</p></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>주목할 선수</h2><button class="ghost lineup-btn" data-nav="roster">전체 보기</button></div><div class="table-scroll"><table><tbody>${[...state.players].sort((a,b)=>overall(b)-overall(a)).slice(0,3).map(p=>`<tr><td><button class="ghost player-name" data-player="${p.id}">${portrait(p)}<span><strong>${esc(p.name)}</strong><small>${p.role} · ${weapons[p.weapon].name}</small></span></button></td><td><span class="rating">${overall(p)}</span></td><td>${'<span class="pill">'+p.age+'세</span>'}</td></tr>`).join('')}</tbody></table></div></section></div><p class="footer-note">첫 버전: 8팀 국내 리그와 다섯 경기 종목. 점수는 센서 피해 판정이며, 현재 경기의 피로는 세트 사이에 이어집니다. 모든 세트 최대 시간은 인게임 60분입니다. 깃발전은 3개 운반 시 조기 종료, 데스매치는 3분 리스폰 후 킬 수로 승부합니다. 시간 종료 동점은 잔여 피해 여유 → 추첨 순으로 처리합니다.</p>`;mountArena();updateMatchUI();}
function playerRow(p,opts={}){return `<tr><td><button class="ghost player-name" data-player="${p.id}">${portrait(p)}<span><strong>${esc(p.name)}</strong><small>${p.country} · ${p.age}세</small></span></button></td><td>${p.role}</td><td>${weapons[p.weapon].name}</td><td><span class="rating">${overall(p)}</span></td><td><span>${Math.round(100-p.fatigue)}%</span><div class="bar"><i style="width:${100-p.fatigue}%"></i></div></td><td>${p.record.kills} / ${p.record.deaths} / ${p.record.assists}</td><td>${value(p)}백만</td><td>${opts.lineup?`<button class="lineup-btn ${selected.has(p.id)?'selected':''}" data-select="${p.id}">${selected.has(p.id)?'출전 우선':'대기'}</button>`:opts.youth?`<button class="lineup-btn" data-promote="${p.id}" ${state.players.length>=30?'disabled':''}>1군 승격</button>`:''}</td></tr>`;}
function renderRoster(c){const list=state.players.filter(p=>(!rosterFilter||p.name.includes(rosterFilter))&&(!roleFilter||p.role===roleFilter));c.innerHTML=title('SQUAD MANAGEMENT','선수단',`${state.players.length} / 30명 등록 · 주전과 종목별 전문 선수를 관리하세요.`,`<span class="pill lime">출전 우선 ${selected.size} / 20</span>`)+`<div class="filters"><input id="roster-search" placeholder="선수 이름 검색" aria-label="선수 이름 검색" value="${esc(rosterFilter)}"><select id="role-filter" aria-label="포지션 필터"><option value="">모든 포지션</option>${roles.map(r=>`<option ${roleFilter===r?'selected':''}>${r}</option>`).join('')}</select><button data-action="auto-lineup">자동 선발</button></div><section class="panel table-scroll"><table><thead><tr><th>선수</th><th>역할</th><th>주력 무기</th><th>OVR</th><th>컨디션</th><th>K / D / A</th><th>시장 추정가</th><th>출전</th></tr></thead><tbody>${list.map(p=>playerRow(p,{lineup:true})).join('')||'<tr><td colspan="8" class="empty">조건에 맞는 선수가 없습니다.</td></tr>'}</tbody></table></section><div class="info section-gap">출전 우선 선수들이 먼저 편성됩니다. 섬멸전 11명, 점령전 20명, 데스매치 9명, 왕잡기 5명을 순서대로 선발하며 에이스는 역할 오버롤이 가장 높은 선수가 출전합니다. 세트 사이에는 피해 점수가 초기화되고 피로가 이어집니다.</div>`;}
function renderTactics(c){c.innerHTML=title('TACTICAL BOARD','전술 설정','선수 구성과 경기 운영 방향을 결정하세요.')+`<div class="grid three">${[['균형','거리 유지와 공격을 균형 있게 수행합니다.'],['공격','이동 속도 +10%, 유효타 확률 +3%p. 적극적으로 교전을 만듭니다.'],['수비','방어 확률 +6%p. 상대 공격을 받아내며 승부합니다.']].map(([t,desc])=>`<section class="panel tactic-card ${state.tactic===t?'active':''}"><span class="eyebrow">TEAM INSTRUCTION</span><h3 class="section-gap">${t}</h3><p>${desc}</p><button class="${state.tactic===t?'primary':''} full" data-tactic="${t}">${state.tactic===t?'적용 중':'적용'}</button></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2>종목별 작전</h2></div><div class="table-scroll"><table><thead><tr><th>종목</th><th>출전 인원</th><th>핵심 역할</th><th>현재 경기 규칙</th></tr></thead><tbody>${modes.map((m,i)=>`<tr><td>${i+1}. ${m.name}</td><td>${m.n}명</td><td>${['선봉 · 견제 · 사격','깃발 탈취 · 운반 · 호위','돌격 · 기동 · 사격','호위 · 교란 · 기동','개인전 전문 선수'][i]}</td><td>${m.rule}</td></tr>`).join('')}</tbody></table></div></section><div class="grid two section-gap"><section class="panel panel-body"><h2>선발 우선순위</h2><p class="muted">출전 우선으로 선택한 선수 중, 역할 순으로 정렬해 각 종목의 선발을 구성합니다.</p><select id="lineup-order" class="full" aria-label="선발 우선순위"><option value="current">현재 순서</option><option value="attack">돌격·선봉 우선</option><option value="defense">수비·호위 우선</option><option value="mobile">기동·교란 우선</option><option value="rating">오버롤 우선</option></select><button class="full section-gap" data-nav="roster">출전 선수 선택</button></section><section class="panel panel-body"><h2>개인 능력과 전술</h2><p class="muted">무기 숙련도, 사거리, 방어, 판단력, 체력과 지형이 실제 공격 판정에 반영됩니다. 오버롤만으로 승패를 결정하지 않습니다.</p><div class="info">왕잡기의 왕은 해당 세트 첫 번째 출전 선수입니다. 에이스전은 양 팀 최고 오버롤 선수가 자동 선발됩니다.</div></section></div>`;}
function estimate(p){const confidence=Math.min(100,p.scout+state.facilities.scouting*10+state.staff.scout*8);const v=value(p),error=(100-confidence)/100*.55;return {low:Math.round(v*(1-error)),high:Math.round(v*(1+error)),confidence};}
function renderMarket(c){const list=state.market.filter(p=>!marketFilter||p.name.includes(marketFilter)||p.country.includes(marketFilter));c.innerHTML=title('RECRUITMENT','이적 · 자유계약 시장','경기 실적과 스카우트 보고서를 비교해 영입하세요.',`<span class="pill">남은 등록 자리 ${30-state.players.length}</span>`)+`<div class="filters"><input id="market-search" placeholder="이름 또는 국적 검색" aria-label="시장 선수 검색" value="${esc(marketFilter)}"><button data-action="scout-event">지역 인재 탐색 · 12백만</button></div><div class="grid four">${list.map(p=>{const e=estimate(p);return `<article class="player-card">${portrait(p,'card-portrait')}<div class="body"><div class="card-top"><span class="pill">자유계약</span><span class="rating">${Math.max(1,overall(p)-Math.round((100-e.confidence)/15))}–${Math.min(100,overall(p)+Math.round((100-e.confidence)/15))}</span></div><h3>${esc(p.name)}</h3><p>${p.country} · ${p.age}세 · ${p.role}</p><p>${weapons[p.weapon].name} · 평가 신뢰도 ${e.confidence}%</p><div class="flex spread"><span class="muted">구단 평가액</span><strong>${e.low}–${e.high}백만</strong></div><button data-player="${p.id}">스카우트 보고서</button></div></article>`;}).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}</div><p class="footer-note">현재 버전의 시장은 자유계약 선수 중심입니다. 계약금은 시장 추정가의 35%, 계약 기간은 2시즌입니다. 구단 간 이적료 협상은 다음 단계에서 확장합니다.</p>`;}
const facilities=[['training','통합 훈련센터','무기·신체·전술 훈련의 성장 확률을 높입니다.'],['medical','의료 · 회복센터','하루 피로 회복량을 높이고 선수단 회복을 지원합니다.'],['scouting','스카우트 센터','선수 가치와 잠재력 보고서의 평가 정확도를 높입니다.'],['youth','유스 아카데미','새 유망주 모집 인원과 기초 육성 수준을 높입니다.']];
function renderFacilities(c){c.innerHTML=title('CLUB DEVELOPMENT','육성 · 시설','훈련 방향을 정하고 구단의 기반에 투자하세요.')+`<section class="panel panel-body"><div class="flex spread wrap"><div><strong>이번 주 훈련</strong><p class="muted">7일마다 성장 판정 · 잠재력과 시설 수준에 따라 성장</p></div><select id="training" aria-label="훈련 방향">${['균형','체력','전술','무기'].map(t=>`<option ${t===state.training?'selected':''}>${t}</option>`).join('')}</select></div></section><div class="grid four section-gap">${facilities.map(([id,name,desc])=>`<section class="panel facility-card"><h3>${name}</h3><p>${desc}</p><div class="facility-level">LV. ${state.facilities[id]} <span class="muted">/ 5</span></div><div class="bar"><i style="width:${state.facilities[id]*20}%"></i></div><button data-upgrade="${id}" ${state.facilities[id]>=5?'disabled':''}>${state.facilities[id]>=5?'최대 수준':'확장 · '+state.facilities[id]*65+'백만'}</button></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2>스태프</h2><span class="muted">첫 버전에서는 담당 팀 수준으로 관리</span></div><div class="grid three panel-body">${[['coach','코칭 팀','훈련 방향과 선수 육성'],['analyst','분석 팀','상대 전력 보고서의 신뢰도'],['scout','스카우트 팀','선수 능력·시장 가치 평가']].map(([id,n,d])=>`<div><strong>${n} · LV.${state.staff[id]}</strong><p class="muted">${d}</p><button data-staff="${id}" ${state.staff[id]>=5?'disabled':''}>보강 · ${state.staff[id]*40}백만</button></div>`).join('')}</div></section><section class="panel section-gap"><div class="panel-head"><h2>유스 선수단 · ${state.youth.length}명</h2><button data-action="youth-recruit">유망주 모집 · 25백만</button></div><div class="table-scroll"><table><thead><tr><th>선수</th><th>역할</th><th>무기</th><th>OVR</th><th>컨디션</th><th>K / D / A</th><th>평가액</th><th>승격</th></tr></thead><tbody>${state.youth.map(p=>playerRow(p,{youth:true})).join('')}</tbody></table></div></section><p class="footer-note">생활관·환경 훈련장·장비 공방 등 전체 시설 구성과 스태프 개인 경력은 이후 확장 대상입니다. 매주 급료와 시설 유지비가 지출됩니다.</p>`;}
function renderLeague(c){const rank=ranked();c.innerHTML=title('COMPETITION','리그 현황','국내 승강 리그에서 출발해 대륙과 월드 무대를 향합니다.',`<span class="pill lime">${state.division||'도시 리그'} · ${state.season}</span>`)+`<div class="grid four">${[['도시 리그','현재 플레이 가능'],['도 리그','국내 승격 단계'],['대륙 리그','국내 성적으로 출전'],['월드리그','대륙 정상급 팀 참가']].map(([n,d],i)=>`<div class="panel stat-card"><div class="value">0${i+1}</div><strong>${n}</strong><p>${d}</p></div>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2>시즌 순위</h2><span class="muted">상위 2팀 승격 · 하위 2팀 강등</span></div><div class="table-scroll"><table><thead><tr><th>순위</th><th>구단</th><th>경기</th><th>승</th><th>패</th><th>세트 득</th><th>세트 실</th><th>득실차</th></tr></thead><tbody>${rank.map((t,i)=>`<tr class="${t.id===0?'ours':''}"><td><span class="rating" style="color:${i<2?'var(--accent)':i>5?'var(--red)':'var(--text)'}">${i+1}</span></td><td><strong>${t.name}</strong> ${t.id===0?'<span class="pill lime">내 구단</span>':''}</td><td>${t.played}</td><td>${t.wins}</td><td>${t.losses}</td><td>${t.for}</td><td>${t.against}</td><td>${t.for-t.against}</td></tr>`).join('')}</tbody></table></div></section><div class="grid two section-gap"><section class="panel"><div class="panel-head"><h2>경기 결과</h2></div>${state.history.length?state.history.slice(0,8).map(h=>`<div class="news-row flex spread"><span><span class="muted">R${h.round}</span> ${h.opponent}</span><strong class="${h.win?'accent':''}">${h.score}</strong></div>`).join(''):'<div class="empty">첫 경기의 결과를 기다리고 있습니다.</div>'}</section><section class="panel"><div class="panel-head"><h2>남은 일정</h2></div>${state.schedule.slice(state.round,state.round+8).map((ps,i)=>{const pair=ps.find(p=>p.includes(0));const op=state.table[pair.find(id=>id!==0)];return `<div class="news-row flex spread"><span><span class="muted">R${state.round+i+1}</span> ${op.name}</span><span class="pill">${pair[0]===0?'홈':'원정'} · ${terrainInfo[pair[0]===0?'city':op.terrain].name}</span></div>`;}).join('')||'<div class="empty">모든 경기가 종료되었습니다.</div>'}</section></div><div class="info section-gap">현재 버전은 국내 8팀 리그를 플레이합니다. 시즌 종료 시 승강 상태를 기록하지만, 상위 리그의 별도 구단 구성과 국제대회 일정은 아직 구현 전입니다.</div>`;}
function renderRelations(c){const adults=state.players.filter(p=>p.age>=18&&!p.youth);c.innerHTML=title('PEOPLE & RELATIONSHIPS','인물 관계','업무 신뢰와 개인 호감은 별도로 관리됩니다.')+`<div class="grid four">${adults.map(p=>`<article class="player-card">${portrait(p,'card-portrait')}<div class="body"><div class="card-top"><span class="pill ${p.relationship==='연애'?'lime':''}">${p.relationship}</span><span class="muted">${p.personality}</span></div><h3>${esc(p.name)}</h3><p>${p.role} · ${p.age}세</p><div class="flex spread"><span class="muted">호감</span><strong>${p.affinity}</strong></div><div class="bar"><i style="width:${p.affinity}%;background:var(--accent)"></i></div><p>신뢰 ${p.trust} · 사기 ${p.morale}</p><button data-talk="${p.id}" ${state.talkDay[p.id]===state.day?'disabled':''}>${state.talkDay[p.id]===state.day?'오늘 대화 완료':'대화하기'}</button></div></article>`).join('')}</div><p class="footer-note">성인 1군 인물에게만 개인 관계 이벤트가 적용됩니다. 연애 감정은 전투 능력이나 출전 우선순위에 직접 보너스를 주지 않습니다.</p>`;}
function openDialog(html){const d=$('#detail');d.innerHTML=`<button class="dialog-close ghost" data-action="close-dialog" aria-label="창 닫기">닫기</button>${html}`;if(!d.open)d.showModal();}
function findPlayer(id){return [...state.players,...state.market,...state.youth].find(p=>p.id===+id);}
function detail(p){const market=state.market.includes(p),youth=state.youth.includes(p),e=estimate(p);const potentialMin=Math.max(overall(p),Math.round(p.pa/2-(100-e.confidence)*.2)),potentialMax=Math.min(100,Math.round(p.pa/2+(100-e.confidence)*.2));openDialog(`<div class="detail-grid"><div>${portrait(p,'portrait large')}<div class="trait"><strong>${p.unique!=null?uniques[p.unique].trait.name:p.personality}</strong><p>${p.unique!=null?uniques[p.unique].trait.text:'훈련과 경기 경험을 통해 자신만의 경력을 쌓습니다.'}</p></div><div class="detail-meta">${p.country} · ${p.sex} · ${p.age}세<br>${p.appearance.height}cm · ${p.appearance.hair} 머리</div></div><div><div class="eyebrow">PLAYER PROFILE</div><h2>${esc(p.name)}</h2><p class="muted">${p.role} · ${weapons[p.weapon].name} · 무기 숙련 ${p.mastery}/20</p><div class="grid three"><div class="panel stat-card"><p>역할 OVR</p><div class="value">${market?`${Math.max(1,overall(p)-Math.round((100-e.confidence)/15))}–${Math.min(100,overall(p)+Math.round((100-e.confidence)/15))}`:overall(p)}</div></div><div class="panel stat-card"><p>잠재력 평가</p><div class="value">${potentialMin}–${potentialMax}</div></div><div class="panel stat-card"><p>시장 추정가</p><div class="value">${value(p)}</div><p>백만원</p></div></div><div class="stats-grid section-gap">${Object.entries(stats).map(([k,n])=>`<div class="stat-line"><span>${n}</span><b>${market?`${Math.max(1,p.stats[k]-Math.ceil((100-e.confidence)/25))}–${Math.min(20,p.stats[k]+Math.ceil((100-e.confidence)/25))}`:p.stats[k]}</b></div>`).join('')}</div><p class="muted">${p.record.games}세트 출전 · ${p.record.kills}킬 / ${p.record.deaths}데스 / ${p.record.assists}어시스트 · 명성 ${p.fame}</p><div class="dialog-actions">${market?`<button data-scout="${p.id}">추가 관찰 · 8백만</button><button class="primary" data-sign="${p.id}" ${state.players.length>=30?'disabled':''}>계약 · ${Math.ceil(value(p)*.35)}백만</button>`:youth?`<button class="primary" data-promote="${p.id}" ${state.players.length>=30?'disabled':''}>1군 승격</button>`:`<button data-talk="${p.id}" ${state.talkDay[p.id]===state.day?'disabled':''}>개인 대화</button><button class="danger" data-release="${p.id}">계약 해지</button>`}</div>${state.players.length>=30&&(market||youth)?'<p class="muted">로스터가 가득 찼습니다. 기존 선수의 자리를 먼저 확보하세요.</p>':''}</div></div>`);}
function talk(p){if(state.talkDay[p.id]===state.day)return toast('오늘은 이미 대화했습니다.');if(p.age<18||p.youth)return;const romantic=p.affinity>=60&&p.trust>=60;const scene=p.relationship==='연애'?`${p.name}이 훈련을 마치고 감독실에 들렀습니다. “오늘은 경기 얘기 말고, 같이 저녁 먹을래요?”`:romantic?`${p.name}이 잠시 머뭇거리다 말을 꺼냅니다. “감독님과 함께하는 시간이 좋아요. 경기장 밖에서도 만나고 싶어요.”`:p.affinity>=25?`${p.name}과 훈련 후 이야기를 나눕니다. “요즘은 경기장 밖에서 뭘 하며 지내세요?”`:`${p.name}이 다음 경기 준비에 대해 의견을 묻습니다. “제 역할에 대해 감독님의 생각을 듣고 싶어요.”`;
openDialog(`<div class="detail-grid"><div>${portrait(p,'portrait large')}<p class="muted">${p.relationship} · 호감 ${p.affinity} · 신뢰 ${p.trust}</p></div><div><div class="eyebrow">PERSONAL MOMENT</div><h2>${esc(p.name)}</h2><p class="event-scene">${esc(scene)}</p><div class="event-options"><button data-choice="listen" data-id="${p.id}">이야기를 듣고 함께 시간을 보낸다</button><button data-choice="work" data-id="${p.id}">선수의 목표와 훈련 계획을 함께 이야기한다</button>${romantic&&p.relationship!=='연애'?`<button class="primary" data-choice="date" data-id="${p.id}">나도 같은 마음이라고 답하고 데이트를 약속한다</button>`:''}${p.relationship==='연애'?`<button data-choice="break" data-id="${p.id}">관계를 정리하고 싶다고 솔직하게 이야기한다</button>`:''}<button data-choice="respect" data-id="${p.id}">오늘은 쉬고 다음에 이야기하자고 배려한다</button></div></div></div>`);}
function startMatch(){if(series&&!series.finished)return;const f=nextFixture(state);if(!f)return;const order=[...state.players.filter(p=>selected.has(p.id)),...state.players.filter(p=>!selected.has(p.id))];if(order.filter(p=>!p.injury).length<20)return toast('점령전에 출전할 수 있는 선수 20명이 필요합니다.');const enemies=enemyRoster(state);series={opponent:f.opponent.name,terrain:f.terrain,rosters:[structuredClone(order),enemies],wins:[0,0],mode:0,results:[],records:[],finished:false};battle=new Battle(series.rosters,0,state.seed,state.tactic,f.terrain);running=true;tab='command';shell();save();}
function finishSet(){running=false;const w=battle.winner;series.wins[w]++;series.results.push(w);for(const u of battle.units){series.records.push({id:u.id,team:u.team,kills:u.kills,deaths:u.deaths,assists:u.assists,objectives:Math.round(u.objectives),aceWin:battle.modeIndex===4&&u.team===w});const p=series.rosters[u.team].find(p=>p.id===u.id);p.fatigue=clamp(100-u.energy+7,0,90);}
if(series.wins[w]>=3){series.finished=true;for(const r of series.records.filter(r=>r.team===0)){const p=state.players.find(p=>p.id===r.id);p.record.games++;p.record.kills+=r.kills;p.record.deaths+=r.deaths;p.record.assists+=r.assists;p.record.objectives+=r.objectives;p.record.aceWins+=r.aceWin?1:0;p.fame=Math.min(100,p.fame+(r.kills>0?1:0));const temp=series.rosters[0].find(v=>v.id===p.id);p.fatigue=temp.fatigue;}finishFixture(state,series.wins);save();shell();}else{const next=series.mode+1;openDialog(`<div class="eyebrow">SET ${series.mode+1} COMPLETE</div><h2>${w===0?'우리 팀':'상대 팀'} 세트 승리</h2><p class="event-scene">현재 스코어 <strong class="accent">${series.wins.join(' : ')}</strong></p><div class="info">다음: ${modes[next].rule}<br>피해 점수는 초기화되고 선수 피로는 이어집니다.</div><div class="dialog-actions"><button class="primary" data-action="next-set">${modes[next].name} 시작</button></div>`);updateMatchUI();}}
function nextSet(){if(!series||series.finished||!battle.done)return;$('#detail').close();series.mode++;battle=new Battle(series.rosters,series.mode,battle.rng.seed,state.tactic,series.terrain);running=true;shell();}
function updateMatchUI(){if(tab!=='command'||!battle)return;const active=series&&!series.finished;const timer=$('#timer');if(timer)timer.textContent=clock(battle.time)+' / 60:00';if($('#match-score'))$('#match-score').textContent=series?series.wins.join(' : '):'0 : 0';if($('#pause'))$('#pause').textContent=running?'일시정지':'재생';if($('#log'))$('#log').innerHTML=battle.logs.slice(0,15).map(l=>`<div class="log-row"><time>${clock(l.time)}</time><span>${esc(l.text)}</span></div>`).join('');if($('#live-score'))$('#live-score').textContent=active&&[1,2].includes(series.mode)?`${series.mode===1?'깃발 운반':'킬'} ${Math.floor(battle.scores[0])} : ${Math.floor(battle.scores[1])}`:'';
if($('#arena-count'))$('#arena-count').textContent=active?`생존 ${battle.alive(0).length} : ${battle.alive(1).length} · ${running?'진행 중':battle.done?'세트 종료':'일시정지'}`:'선수 입장 · 경기 시작을 기다립니다';
if($('#status-list'))$('#status-list').innerHTML=battle.units.filter(u=>u.team===0).map(u=>`<div class="status-row ${!u.alive?'out':''}"><strong>${esc(u.p.name)}${u.king?' ♛':''}</strong><div class="bars"><div class="bar" title="남은 피해 여유"><i style="width:${u.hp}%;background:var(--accent)"></i></div><div class="bar" title="체력"><i style="width:${u.energy}%"></i></div></div><span>${!u.alive?(series.mode===2?clock(Math.max(0,u.respawn-battle.time)):'OUT'):u.flagId!==null?'깃발 운반':!u.armed?'맨손':u.kills+'K'}</span></div>`).join('');for(let i=0;i<5;i++){const ch=$('#chip-'+i);if(ch)ch.className='set-chip '+(active&&series.mode===i?'current ':'')+(series?.results[i]===0?'win':series?.results[i]===1?'loss':'');}}
function loop(ts){requestAnimationFrame(loop);if(!lastTick)lastTick=ts;const dt=Math.min(.1,(ts-lastTick)/1000);lastTick=ts;if(running&&battle&&!battle.done){loop.acc=(loop.acc||0)+dt*speed;while(loop.acc>=.5&&!battle.done){battle.step(.5);loop.acc-=.5;}if(battle.done){loop.acc=0;finishSet();}}uiTick+=dt;if(uiTick>.35){uiTick=0;updateMatchUI();}}
function spend(n){if(state.budget<n){toast('구단 예산이 부족합니다.');return false;}state.budget-=n;return true;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav){tab=b.dataset.nav;shell();return;}if(b.dataset.player){const p=findPlayer(b.dataset.player);if(p)detail(p);return;}if(b.dataset.camera&&arena){if(b.dataset.camera==='rotate')arena.orbit+=.45;if(b.dataset.camera==='in')arena.zoom=Math.max(.6,arena.zoom-.12);if(b.dataset.camera==='out')arena.zoom=Math.min(1.6,arena.zoom+.12);return;}if(b.dataset.select){const id=+b.dataset.select;if(selected.has(id))selected.delete(id);else if(selected.size<20)selected.add(id);else return toast('출전 우선은 최대 20명입니다.');save();renderContent();return;}if(b.dataset.tactic){state.tactic=b.dataset.tactic;save();renderContent();toast('전술을 적용했습니다.');return;}if(b.dataset.upgrade){const id=b.dataset.upgrade;if(!['training','medical','scouting','youth'].includes(id))return;const lv=state.facilities[id];if(lv<5&&spend(lv*65)){state.facilities[id]++;save();shell();toast('시설 확장이 완료되었습니다.');}return;}if(b.dataset.staff){const id=b.dataset.staff;const lv=state.staff[id];if(lv<5&&spend(lv*40)){state.staff[id]++;save();shell();toast('스태프 팀을 보강했습니다.');}return;}if(b.dataset.scout){const p=findPlayer(b.dataset.scout);if(p&&spend(8)){p.scout=Math.min(100,p.scout+20+state.staff.scout*4);save();detail(p);toast('추가 관찰 결과를 반영했습니다.');}return;}if(b.dataset.sign){const p=findPlayer(b.dataset.sign);if(p&&state.market.includes(p)&&state.players.length<30&&spend(Math.ceil(value(p)*.35))){state.market=state.market.filter(x=>x.id!==p.id);p.team=0;p.contract=state.season+2;state.players.push(p);$('#detail').close();save();shell();toast(p.name+' 선수와 계약했습니다.');}return;}if(b.dataset.release){const p=findPlayer(b.dataset.release);if(!p)return;openDialog(`<h2>계약 해지</h2><p class="event-scene">${esc(p.name)} 선수를 자유계약 시장으로 보내시겠습니까?</p><p class="muted">위약금 ${p.wage*3}백만원 · 선수와의 신뢰가 감소합니다.</p><button class="danger" data-confirm-release="${p.id}">계약 해지 확정</button>`);return;}if(b.dataset.confirmRelease){const p=findPlayer(b.dataset.confirmRelease);if(p&&spend(p.wage*3)){state.players=state.players.filter(x=>x.id!==p.id);selected.delete(p.id);p.team=-1;p.trust=Math.max(0,p.trust-15);state.market.push(p);$('#detail').close();save();shell();toast('계약을 해지했습니다.');}return;}if(b.dataset.promote){const p=findPlayer(b.dataset.promote);if(p&&state.youth.includes(p)&&state.players.length<30){state.youth=state.youth.filter(x=>x.id!==p.id);p.youth=false;p.team=0;state.players.push(p);$('#detail').close();save();shell();toast('1군으로 승격했습니다.');}return;}if(b.dataset.talk){const p=findPlayer(b.dataset.talk);if(p)talk(p);return;}if(b.dataset.choice){const p=findPlayer(b.dataset.id);if(!p||state.talkDay[p.id]===state.day)return;const ch=b.dataset.choice;if(ch==='listen'){p.affinity=clamp(p.affinity+7,0,100);p.trust=clamp(p.trust+3,0,100);}if(ch==='work'){p.trust=clamp(p.trust+8,0,100);p.affinity=clamp(p.affinity+3,0,100);}if(ch==='respect'){p.trust=clamp(p.trust+2,0,100);}if(ch==='date'&&p.affinity>=60&&p.trust>=60){p.relationship='연애';p.affinity=clamp(p.affinity+5,0,100);}if(ch==='break'){p.relationship='친밀';p.affinity=Math.max(20,p.affinity-20);}if(p.relationship!=='연애')p.relationship=p.affinity>=40?'친밀':p.affinity>=20?'친분':'업무 관계';state.talkDay[p.id]=state.day;$('#detail').close();save();shell();toast(ch==='date'?'서로의 마음을 확인했습니다.':'대화를 마쳤습니다.');return;}
const action=b.dataset.action;if(action==='close-dialog')$('#detail').close();if(action==='save')save(false);if(action==='day'){advance(state);save();shell();toast('하루가 지났습니다.');}if(action==='kickoff')startMatch();if(action==='pause'){if(!series||series.finished)return;if(battle.done){nextSet();return;}running=!running;updateMatchUI();}if(action==='next-set')nextSet();if(action==='quick'){if(!series||series.finished||battle.done)return;running=false;for(let i=0;i<Math.ceil(battle.mode.time/.5)+1&&!battle.done;i++)battle.step(.5);if(battle.done)finishSet();}if(action==='close-result'){series=null;battle=null;running=false;shell();}if(action==='auto-lineup'){selected=new Set([...state.players].sort((a,b)=>overall(b)-overall(a)).slice(0,20).map(p=>p.id));renderContent();toast('상위 20명을 출전 우선으로 선택했습니다.');}if(action==='scout-event'){if(spend(12)){const p=player(state,{team:-1,level:rand(state)<.2?2:0});const place=rand(state)<.5?'길거리 공개 테스트':'지하 격투장';p.scout=50;state.market.unshift(p);state.news.unshift({day:state.day,title:'지역 인재 발견',text:`${place}에서 ${p.name}을 발견했습니다.`});save();shell();detail(p);} }if(action==='youth-recruit'){if(state.youth.length>=20)return toast('유스 수용 인원은 최대 20명입니다.');if(spend(25)){for(let i=0;i<Math.min(state.facilities.youth+1,20-state.youth.length);i++)state.youth.push(player(state,{youth:true,team:-2}));save();shell();toast('새 유망주가 입단했습니다.');}}if(action==='new-season'){if(state.round<14)return;const rank=ranked().findIndex(t=>t.id===0)+1;state.division=rank<=2?'도 리그':rank>=7?'지역 예선':'도시 리그';state.season++;state.day=0;state.round=0;for(const t of state.table)Object.assign(t,{played:0,wins:0,losses:0,for:0,against:0});for(const p of [...state.players,...state.youth,...state.market]){p.age++;if(p.age>=30)for(const k of ['speed','accel','agility'])if(rand(state)<.25)p.stats[k]=Math.max(1,p.stats[k]-1);}state.news.unshift({day:0,title:'새 시즌',text:`지난 시즌 ${rank}위. ${state.division} 단계로 기록되었습니다. 별도 상위 리그 편성은 다음 버전에서 추가됩니다.`});series=null;battle=null;save();shell();}if(action==='reset'){openDialog('<h2>새 게임</h2><p class="event-scene">현재 게임의 저장을 초기화합니다. 필요하면 먼저 저장 파일을 내보내세요.</p><button class="danger" data-action="confirm-reset">새 게임 시작</button>');}if(action==='confirm-reset'){state=createWorld();selected=new Set(state.players.slice(0,20).map(p=>p.id));series=null;battle=null;running=false;tab='command';$('#detail').close();save();shell();}if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`arena-${state.season}-day${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.');}if(action==='import')$('#save-file').click();});
document.addEventListener('change',async e=>{if(e.target.id==='speed')speed=+e.target.value;if(e.target.id==='live-tactic'){state.tactic=e.target.value;if(battle)battle.tactic=state.tactic;toast('전술 지시를 전달했습니다.');}if(e.target.id==='training'){state.training=e.target.value;save();toast('훈련 방향을 변경했습니다.');}if(e.target.id==='role-filter'){roleFilter=e.target.value;renderContent();}if(e.target.id==='lineup-order'){const order={attack:['돌격','선봉','견제'],defense:['수비','호위','견제'],mobile:['기동','교란','사격']};const type=e.target.value;if(type==='rating')state.players.sort((a,b)=>overall(b)-overall(a));else if(order[type])state.players.sort((a,b)=>(order[type].includes(b.role)?1:0)-(order[type].includes(a.role)?1:0));save();toast('선발 순서를 변경했습니다.');}if(e.target.id==='save-file'&&e.target.files[0]){try{const loaded=JSON.parse(await e.target.files[0].text());if(loaded.version!==1||!Array.isArray(loaded.market)||!Array.isArray(loaded.youth)||typeof loaded.club!=='string'||loaded.club.length>60||!Array.isArray(loaded.players)||loaded.players.length>30||loaded.players.length<20||!Array.isArray(loaded.table)||loaded.table.length!==8||!loaded.schedule||!loaded.facilities||!loaded.staff||!Number.isInteger(loaded.seed))throw Error();for(const p of [...loaded.players,...loaded.market,...loaded.youth])if(!p.stats||!p.record||!Number.isInteger(p.weapon)||p.weapon<0||p.weapon>=weapons.length||!Number.isFinite(p.age)||p.unique!=null&&(!Number.isInteger(p.unique)||p.unique<0||p.unique>=100))throw Error();state=loaded;normalizeDiscoveryNews(state);selected=new Set(state.players.slice(0,20).map(p=>p.id));series=null;battle=null;running=false;save();shell();toast('저장 파일을 불러왔습니다.');}catch{toast('호환되는 ARENA 저장 파일이 아닙니다.');}}});
document.addEventListener('input',e=>{if(e.target.id==='roster-search'){const start=e.target.selectionStart;rosterFilter=e.target.value;renderContent();$('#roster-search').focus();$('#roster-search').setSelectionRange(start,start);}if(e.target.id==='market-search'){const start=e.target.selectionStart;marketFilter=e.target.value;renderContent();$('#market-search').focus();$('#market-search').setSelectionRange(start,start);}});
const context=document.modelContext;if(context?.registerTool){for(const tool of [{name:'read_arena_club',description:'현재 구단 예산, 선수단, 다음 경기 정보를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({club:state.club,budget:state.budget,players:state.players.map(p=>({id:p.id,name:p.name,role:p.role,overall:overall(p)})),fixture:nextFixture(state)})},{name:'set_arena_tactic',description:'구단 전술을 설정하고 현재 화면에 반영합니다.',inputSchema:{type:'object',properties:{tactic:{type:'string',enum:['균형','공격','수비']}},required:['tactic'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['균형','공격','수비'].includes(input.tactic))throw Error('잘못된 전술');state.tactic=input.tactic;if(battle)battle.tactic=input.tactic;if(!series||series.finished)save();shell();return {tactic:state.tactic};}}])try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}
shell();save();requestAnimationFrame(loop);
